31	template <typename T>
32	std::unique_ptr<TilingBaseClass> TILING_CLASS(gert::TilingContext* context)
33	{
34	    return std::unique_ptr<T>(new (std::nothrow) T(context));
35	}
36	
37	using TilingClassCase = std::unique_ptr<TilingBaseClass> (*)(gert::TilingContext*);
38	
39	class TilingCases {
40	public:
41	    explicit TilingCases(std::string op_type) : op_type_(std::move(op_type)) {}
42	
43	    template <typename T>
44	    void AddTiling(int32_t priority)
45	    {
46	        OP_CHECK_IF(cases_.find(priority) != cases_.end(), OP_LOGE(op_type_, "There are duplicate registrations."),
47	                    return );
48	        cases_[priority] = TILING_CLASS<T>;
49	        OP_CHECK_IF(cases_[priority] == nullptr,
50	                    OP_LOGE(op_type_, "Register op tiling func failed, please check the class name."), return );
51	    }
52	
53	    const std::map<int32_t, TilingClassCase>& GetTilingCases() { return cases_; }
54	
55	private:
56	    std::map<int32_t, TilingClassCase> cases_;
57	    const std::string op_type_;
58	};
