60	// --------------------------------Interfacce with npu arch --------------------------------
61	class TilingRegistryArch {
62	public:
63	    TilingRegistryArch() = default;
64	
65	#ifdef ASCENDC_OP_TEST
66	    static TilingRegistryArch& GetInstance();
67	#else
68	    static TilingRegistryArch& GetInstance()
69	    {
70	        static TilingRegistryArch registryImpl;
71	        return registryImpl;
72	    }
73	#endif
74	
75	    std::shared_ptr<TilingCases> RegisterOp(const std::string& opType, int32_t arch)
76	    {
77	        auto archIter = registryMap_.find(arch);
78	        if (archIter == registryMap_.end()) {
79	            std::map<std::string, std::shared_ptr<TilingCases>> opTypeMap;
80	            opTypeMap[opType] = std::shared_ptr<TilingCases>(new (std::nothrow) TilingCases(opType));
81	            registryMap_[arch] = opTypeMap;
82	        } else {
83	            if (archIter->second.find(opType) == archIter->second.end()) {
84	                archIter->second[opType] = std::shared_ptr<TilingCases>(new (std::nothrow) TilingCases(opType));
85	            }
86	        }
87	
88	        OP_CHECK_IF(registryMap_[arch][opType] == nullptr,
89	                    OP_LOGE(opType, "Register tiling func failed, please check the class name."), return nullptr);
90	        return registryMap_[arch][opType];
91	    }
92	
93	    ge::graphStatus DoTilingImpl(gert::TilingContext* context)
94	    {
95	        int32_t arch = (int32_t)NpuArch::DAV_RESV;
96	        const char* opType = context->GetNodeType();
97	        fe::PlatFormInfos* platformInfoPtr = context->GetPlatformInfo();
98	        if (platformInfoPtr == nullptr) {
99	            OP_LOGE(opType, "Do op tiling failed, cannot get platformInfo.");
100	            return ge::GRAPH_FAILED;
101	        } else {
102	            auto ascendcPlatform = platform_ascendc::PlatformAscendC(platformInfoPtr);
103	            arch = static_cast<int32_t>(ascendcPlatform.GetCurNpuArch());
104	            OP_LOGD(context, "npu arch is %d", arch);
105	            if (arch == (int32_t)NpuArch::DAV_RESV) {
106	                OP_LOGE(opType, "Do op tiling failed, cannot find npu arch.");
107	                return ge::GRAPH_FAILED;
108	            }
109	        }
110	        auto tilingTemplateRegistryMap = GetTilingTemplates(opType, arch);
111	        for (auto it = tilingTemplateRegistryMap.begin(); it != tilingTemplateRegistryMap.end(); ++it) {
112	            auto tilingTemplate = it->second(context);
113	            if (tilingTemplate != nullptr) {
114	                ge::graphStatus status = tilingTemplate->DoTiling();
115	                if (status != ge::GRAPH_PARAM_INVALID) {
116	                    OP_LOGD(context, "Do general op tiling success priority=%d", it->first);
117	                    return status;
118	                }
119	                OP_LOGD(context, "Ignore general op tiling priority=%d", it->first);
120	            }
121	        }
122	        OP_LOGE(opType, "Do op tiling failed, no valid template is found.");
123	        return ge::GRAPH_FAILED;
124	    }
125	
126	    ge::graphStatus DoTilingImpl(gert::TilingContext* context, const std::vector<int32_t>& priorities)
127	    {
128	        int32_t arch = static_cast<int32_t>(NpuArch::DAV_RESV);
129	        const char* opType = context->GetNodeType();
130	        if (opType == nullptr) {
131	            opType = "Unknown op";
132	        }
133	        auto platformInfoPtr = context->GetPlatformInfo();
134	        if (platformInfoPtr == nullptr) {
135	            OP_LOGE(opType, "Do op tiling failed, cannot get platformInfo.");
136	            return ge::GRAPH_FAILED;
137	        } else {
138	            auto ascendcPlatform = platform_ascendc::PlatformAscendC(platformInfoPtr);
139	            std::string platformRes;
140	            platformInfoPtr->GetPlatformRes("AICoreintrinsicDtypeMap", "Intrinsic_mmad", platformRes);
141	            bool supportMmadS8S4 = (platformRes.find("s8s4") != std::string::npos);
142	            arch = static_cast<int32_t>(supportMmadS8S4 ? NpuArch::DAV_RESV : ascendcPlatform.GetCurNpuArch());
143	            OP_LOGD(context, "NpuArch is %d", arch);
144	            if (!supportMmadS8S4 && arch == static_cast<int32_t>(NpuArch::DAV_RESV)) {
145	                OP_LOGE(opType, "Do op tiling failed, cannot find npu arch.");
146	                return ge::GRAPH_FAILED;
147	            }
148	        }
149	        auto tilingTemplateRegistryMap = GetTilingTemplates(opType, arch);
150	        for (auto priorityId : priorities) {
151	            auto tilingCaseIter = tilingTemplateRegistryMap.find(priorityId);
152	            if (tilingCaseIter != tilingTemplateRegistryMap.end()) {
153	                auto templateFunc = tilingCaseIter->second(context);
154	                if (templateFunc != nullptr) {
155	                    ge::graphStatus status = templateFunc->DoTiling();
156	                    if (status == ge::GRAPH_SUCCESS) {
157	                        OP_LOGD(context, "Do general op tiling success priority=%d", priorityId);
158	                        return status;
159	                    }
160	                    if (status != ge::GRAPH_PARAM_INVALID) {
161	                        OP_LOGD(context, "Do op tiling failed");
162	                        return status;
163	                    }
164	                    OP_LOGD(context, "Ignore general op tiling priority=%d", priorityId);
165	                }
166	            }
167	        }
168	        return ge::GRAPH_FAILED;
169	    }
170	
171	    ge::graphStatus DoTilingImpl(gert::TilingContext* context, const std::vector<int32_t>& priorities, int32_t arch)
172	    {
173	        const char* opType = context->GetNodeType();
174	        if (opType == nullptr) {
175	            opType = "Unknown op";
176	        }
177	        const auto& tilingTemplateRegistryMap = GetTilingTemplates(opType, arch);
178	        for (auto priorityId : priorities) {
179	            auto tilingCaseIter = tilingTemplateRegistryMap.find(priorityId);
180	            if (tilingCaseIter != tilingTemplateRegistryMap.end()) {
181	                auto templateFunc = tilingCaseIter->second(context);
182	                if (templateFunc != nullptr) {
183	                    ge::graphStatus status = templateFunc->DoTiling();
184	                    if (status == ge::GRAPH_SUCCESS) {
185	                        OP_LOGD(context, "Do general op tiling success priority=%d", priorityId);
186	                        return status;
187	                    }
188	                    if (status != ge::GRAPH_PARAM_INVALID) {
189	                        OP_LOGD(context, "Do op tiling failed");
190	                        return status;
191	                    }
192	                    OP_LOGD(context, "Ignore general op tiling priority=%d", priorityId);
193	                }
194	            }
195	        }
196	        return ge::GRAPH_FAILED;
197	    }
198	
199	    const std::map<int32_t, TilingClassCase>& GetTilingTemplates(const std::string& opType, int32_t arch)
200	    {
201	        auto archIter = registryMap_.find(arch);
202	        OP_CHECK_IF(archIter == registryMap_.end(),
203	                    OP_LOGE(opType, "Get op tiling func failed, please check the npu arch %d", arch),
204	                    return emptyTilingCase_);
205	        auto opIter = archIter->second.find(opType);
206	        OP_CHECK_IF(opIter == archIter->second.end(),
207	                    OP_LOGE(opType, "Get op tiling func failed, please check the op name."), return emptyTilingCase_);
208	        return opIter->second->GetTilingCases();
209	    }
210	
211	private:
212	    std::map<int32_t, std::map<std::string, std::shared_ptr<TilingCases>>> registryMap_; // key is npu-arch
213	    const std::map<int32_t, TilingClassCase> emptyTilingCase_{};
214	};
