216	class RegisterArch {
217	public:
218	    explicit RegisterArch(std::string opType) : opType_(std::move(opType)) {}
219	
220	    template <typename T>
221	    RegisterArch& tiling(int32_t priority, int32_t arch)
222	    {
223	        auto tilingCases = TilingRegistryArch::GetInstance().RegisterOp(opType_, arch);
224	        OP_CHECK_IF(tilingCases == nullptr, OP_LOGE(opType_, "Register op tiling failed, please check the op name."),
225	                    return *this);
226	        tilingCases->AddTiling<T>(priority);
227	        return *this;
228	    }
229	
230	    template <typename T>
231	    RegisterArch& tiling(int32_t priority, const std::vector<int32_t>& archs)
232	    {
233	        for (int32_t arch : archs) {
234	            auto tilingCases = TilingRegistryArch::GetInstance().RegisterOp(opType_, arch);
235	            OP_CHECK_IF(tilingCases == nullptr,
236	                        OP_LOGE(opType_, "Register op tiling failed, please check the op name."), return *this);
237	            tilingCases->AddTiling<T>(priority);
238	        }
239	        return *this;
240	    }
241	
242	private:
243	    const std::string opType_;
244	};
