261	    std::shared_ptr<TilingCases> RegisterOp(const std::string& op_type, int32_t soc_version)
262	    {
263	        auto soc_iter = registry_map_.find(soc_version);
264	        if (soc_iter == registry_map_.end()) {
265	            std::map<std::string, std::shared_ptr<TilingCases>> op_type_map;
266	            op_type_map[op_type] = std::shared_ptr<TilingCases>(new (std::nothrow) TilingCases(op_type));
267	            registry_map_[soc_version] = op_type_map;
268	        } else {
269	            if (soc_iter->second.find(op_type) == soc_iter->second.end()) {
270	                soc_iter->second[op_type] = std::shared_ptr<TilingCases>(new (std::nothrow) TilingCases(op_type));
271	            }
272	        }
273	
274	        OP_CHECK_IF(registry_map_[soc_version][op_type] == nullptr,
275	                    OP_LOGE(op_type, "Register tiling func failed, please check the class name."), return nullptr);
276	        return registry_map_[soc_version][op_type];
277	    }
278	
279	    ge::graphStatus DoTilingImpl(gert::TilingContext* context)
280	    {
281	        int32_t soc_version = (int32_t)platform_ascendc::SocVersion::RESERVED_VERSION;
282	        const char* op_type = context->GetNodeType();
283	        fe::PlatFormInfos* platformInfoPtr = context->GetPlatformInfo();
284	        if (platformInfoPtr == nullptr) {
285	            auto compileInfoPtr = context->GetCompileInfo<CompileInfoCommon>();
286	            OP_CHECK_IF(compileInfoPtr == nullptr, OP_LOGE(op_type, "compileInfoPtr is null."),
287	                        return ge::GRAPH_FAILED);
288	            soc_version = compileInfoPtr->socVersion;
289	            OP_LOGD(context, "soc version in compileInfo is %d", soc_version);
290	        } else {
291	            auto ascendcPlatform = platform_ascendc::PlatformAscendC(platformInfoPtr);
292	            soc_version = static_cast<int32_t>(ascendcPlatform.GetSocVersion());
293	            OP_LOGD(context, "soc version is %d", soc_version);
294	            if (soc_version == (int32_t)platform_ascendc::SocVersion::RESERVED_VERSION) {
295	                OP_LOGE(op_type, "Do op tiling failed, cannot find soc version.");
296	                return ge::GRAPH_FAILED;
297	            }
298	        }
299	        auto tilingTemplateRegistryMap = GetTilingTemplates(op_type, soc_version);
300	        for (auto it = tilingTemplateRegistryMap.begin(); it != tilingTemplateRegistryMap.end(); ++it) {
301	            auto tilingTemplate = it->second(context);
302	            if (tilingTemplate != nullptr) {
303	                ge::graphStatus status = tilingTemplate->DoTiling();
304	                if (status != ge::GRAPH_PARAM_INVALID) {
305	                    OP_LOGD(context, "Do general op tiling success priority=%d", it->first);
306	                    return status;
307	                }
308	                OP_LOGD(context, "Ignore general op tiling priority=%d", it->first);
309	            }
310	        }
311	        OP_LOGE(op_type, "Do op tiling failed, no valid template is found.");
312	        return ge::GRAPH_FAILED;
313	    }
314	
315	    ge::graphStatus DoTilingImpl(gert::TilingContext* context, const std::vector<int32_t>& priorities)
316	    {
317	        int32_t soc_version;
318	        const char* op_type = context->GetNodeType();
319	        auto platformInfoPtr = context->GetPlatformInfo();
320	        if (platformInfoPtr == nullptr) {
321	            auto compileInfoPtr = context->GetCompileInfo<CompileInfoCommon>();
322	            OP_CHECK_IF(compileInfoPtr == nullptr, OP_LOGE(op_type, "compileInfoPtr is null."),
323	                        return ge::GRAPH_FAILED);
324	            soc_version = compileInfoPtr->socVersion;
325	            OP_LOGD(context, "soc version in compileInfo is %d", soc_version);
326	        } else {
327	            auto ascendcPlatform = platform_ascendc::PlatformAscendC(platformInfoPtr);
328	            soc_version = static_cast<int32_t>(ascendcPlatform.GetSocVersion());
329	            OP_LOGD(context, "soc version is %d", soc_version);
330	        }
331	
332	        auto tilingTemplateRegistryMap = GetTilingTemplates(op_type, soc_version);
333	        for (auto priority_id : priorities) {
334	            auto tilingCaseIter = tilingTemplateRegistryMap.find(priority_id);
335	            if (tilingCaseIter != tilingTemplateRegistryMap.end()) {
336	                auto templateFunc = tilingCaseIter->second(context);
337	                if (templateFunc != nullptr) {
338	                    ge::graphStatus status = templateFunc->DoTiling();
339	                    if (status == ge::GRAPH_SUCCESS) {
340	                        OP_LOGD(context, "Do general op tiling success priority=%d", priority_id);
341	                        return status;
342	                    }
343	                    OP_LOGD(context, "Ignore general op tiling priority=%d", priority_id);
344	                }
345	            }
346	        }
347	        return ge::GRAPH_FAILED;
348	    }
349	
350	    const std::map<int32_t, TilingClassCase>& GetTilingTemplates(const std::string& op_type, int32_t soc_version)
351	    {
352	        auto soc_iter = registry_map_.find(soc_version);
353	        OP_CHECK_IF(soc_iter == registry_map_.end(),
354	                    OP_LOGE(op_type, "Get op tiling func failed, please check the soc version %d", soc_version),
355	                    return empty_tiling_case_);
356	        auto op_iter = soc_iter->second.find(op_type);
357	        OP_CHECK_IF(op_iter == soc_iter->second.end(),
358	                    OP_LOGE(op_type, "Get op tiling func failed, please check the op name."),
359	                    return empty_tiling_case_);
360	        return op_iter->second->GetTilingCases();
361	    }
362	
363	private:
364	    std::map<int32_t, std::map<std::string, std::shared_ptr<TilingCases>>> registry_map_; // key is socversion
365	    const std::map<int32_t, TilingClassCase> empty_tiling_case_{};
366	};
