478	class Register {
479	public:
480	    explicit Register(std::string op_type) : op_type_(std::move(op_type)) {}
481	
482	    template <typename T>
483	    Register& tiling(int32_t priority)
484	    {
485	        auto tilingCases = TilingRegistry::GetInstance().RegisterOp(op_type_);
486	        OP_CHECK_IF(tilingCases == nullptr, OP_LOGE(op_type_, "Register op tiling failed, please the op name."),
487	                    return *this);
