495	// op_type: 算子名称， class_name: 注册的 tiling 类, arch：芯片架构号
496	// priority: tiling 类的优先级, 越小表示优先级越高, 即会优先选择这个tiling类
497	#define REGISTER_TILING_TEMPLATE_WITH_ARCH(op_type, class_name, archs, priority)                       \
498	    [[maybe_unused]] uint32_t op_impl_register_template_##op_type##_##class_name##priority;            \
499	    static Ops::NN::Optiling::RegisterArch                                                             \
500	        VAR_UNUSED##op_type##class_name##priority_register = Ops::NN::Optiling::RegisterArch(#op_type) \
501	                                                                 .tiling<class_name>(priority, archs)
502	
503	// op_type: 算子名称， class_name: 注册的 tiling 类, soc_version：芯片版本号
504	// priority: tiling 类的优先级, 越小表示优先级越高, 即会优先选择这个tiling类
